// Repair the menu_items identity sequence.
//
// Symptom: adding a new menu item from the app never reaches the cloud —
// the queued upsert fails with `duplicate key value violates unique
// constraint "menu_items_pkey"` and retries forever.
//
// Cause: menu rows are seeded with explicit ids (1..48), and inserts with
// an explicit value do NOT advance a `GENERATED BY DEFAULT` identity
// sequence. The app's upsert omits `id`, so the next insert asks the
// sequence for a value that is already occupied.
//
// Fix: consume sequence numbers until the generated id is above the current
// max row id (a failed insert still advances the sequence — these are
// non-transactional). Whatever the sequence was, it ends up one ahead of
// max(id) and grows monotonically from there, so plain inserts can never
// collide again. Probe rows are deleted immediately.
//
//   node --env-file=.env scripts/repair-menu-sequence.mjs

import { createClient } from '@supabase/supabase-js';

const url = process.env.VITE_SUPABASE_URL;
const key = process.env.VITE_SUPABASE_PUBLISHABLE_KEY || process.env.VITE_SUPABASE_ANON_KEY;
if (!url || !key) {
  console.error('Missing VITE_SUPABASE_URL / VITE_SUPABASE_PUBLISHABLE_KEY in .env');
  process.exit(1);
}

const supabase = createClient(url, key, {
  auth: { autoRefreshToken: false, persistSession: false },
});

const { error: signInErr } = await supabase.auth.signInWithPassword({
  email: 'manager@maison.de.luxe',
  password: 'admin123',
});
if (signInErr) {
  console.error(`Sign-in failed: ${signInErr.message}`);
  process.exit(1);
}

const { data: rows, error: readErr } = await supabase
  .from('menu_items')
  .select('id');
if (readErr) {
  console.error(`Read failed: ${readErr.message}`);
  process.exit(1);
}
const maxId = Math.max(0, ...(rows || []).map((r) => r.id));
console.log(`menu_items rows: ${rows.length}, max id: ${maxId}`);

// Warm the sequence: keep inserting (no id) until an insert succeeds.
let attempts = 0;
let warmedId = null;
while (attempts < 200) {
  attempts += 1;
  const probeName = `__seqwarm_${attempts}__`;
  const { data: ins, error } = await supabase
    .from('menu_items')
    .insert({ name: probeName, category: 'Breakfast', description: '', price: 1, stock: 0 })
    .select('id')
    .single();
  if (error) {
    if (error.code === '23505') {
      continue; // pkey collision — nextval consumed, try again
    }
    console.error(`Probe insert failed: ${error.message}`);
    process.exit(1);
  }
  warmedId = ins.id;
  if (ins.id > maxId) {
    await supabase.from('menu_items').delete().eq('name', probeName);
    break;
  }
  // Unlikely: unique name probe inserted under max id — shouldn't happen.
  await supabase.from('menu_items').delete().eq('name', probeName);
}
if (warmedId === null || warmedId <= maxId) {
  console.error('Could not advance the sequence — investigate manually.');
  process.exit(1);
}

// Verify with a fresh plain insert (exactly what the app sends).
const { data: verify, error: verifyErr } = await supabase
  .from('menu_items')
  .insert({ name: '__seqverify__', category: 'Breakfast', description: '', price: 1, stock: 0 })
  .select('id')
  .single();
if (verifyErr) {
  console.error(`Verify insert FAILED: ${verifyErr.message}`);
  process.exit(1);
}
await supabase.from('menu_items').delete().eq('name', '__seqverify__');
console.log(`sequence realigned (max ${maxId}); plain insert now returns id ${verify.id} — OK`);